function comment_new_row_callback( $new_comment, $mode ) {
		global $wp_list_table, $post, $comment_level;

		$post       = $this->post;
		$comment_id = $new_comment['id'];
		$comment    = get_comment( $comment_id );

		$globals['comment'] = $comment;

		// make sure wp_comments_list_table has everything it needs.
		if ( empty( $wp_list_table ) ) {
			$wp_list_table = _get_list_table( 'wp_comments_list_table', array( 'screen' => 'edit-comments' ) );
		}

		// determine if we are using a hierarchical or flat comments display.
		$hierarchy = array();
		ob_start();
		if ( get_option( 'thread_comments' ) ) {
			$comment_level = 1;
		} else {
			$comment_level = 0;
		}
		$wp_list_table->single_row( $comment, $comment_level, $hierarchy );
		return ob_get_clean();
	}
